const THEMES={supporter:{color:'#ffd400',bg:'linear-gradient(145deg,#ffe52b 0%,#d4a900 30%,#715500 55%,#251c00 78%,#070600 100%)',border:'#ffd400',shadow:'0 0 0 1px rgba(255,212,0,.5),0 0 26px rgba(255,212,0,.5),0 18px 34px rgba(0,0,0,.3)'},admin:{color:'#050505',bg:'linear-gradient(145deg,#ff2433 0%,#e10d20 32%,#a30716 58%,#57050d 78%,#180205 100%)',border:'#ff3947',shadow:'0 0 0 1px rgba(255,57,71,.42),0 0 24px rgba(255,31,49,.42),0 18px 34px rgba(0,0,0,.32)'},business:{color:'#45c7ff',bg:'linear-gradient(145deg,#42caff 0%,#1399df 30%,#08699e 55%,#073a59 78%,#03141f 100%)',border:'#45c7ff',shadow:'0 0 0 1px rgba(69,199,255,.46),0 0 25px rgba(69,199,255,.42),0 18px 34px rgba(0,0,0,.3)'},member:{color:'#eef2f6',bg:'linear-gradient(145deg,#dce2e8 0%,#aeb8c2 28%,#6f7b87 53%,#36434f 76%,#151d25 100%)',border:'#cbd3db',shadow:'0 0 0 1px rgba(220,226,232,.34),0 0 20px rgba(200,210,220,.25),0 18px 34px rgba(0,0,0,.28)'}};function si(e,p,v){if(e.style.getPropertyValue(p)===v&&e.style.getPropertyPriority(p)==='important')return;e.style.setProperty(p,v,'important')}function paint(s,k){const t=THEMES[k];document.querySelectorAll(s).forEach(e=>{const c=`role-theme-${k}`;if(!e.classList.contains(c))e.classList.add(c);si(e,'background',t.bg);si(e,'border-color',t.border);si(e,'box-shadow',t.shadow);const a=e.querySelector('.member-avatar');if(a){si(a,'border-color',t.border);si(a,'box-shadow',`0 0 0 2px ${t.border}55,0 0 18px ${t.border}88`)}})}function ages(){document.querySelectorAll('.member-card .member-name').forEach(e=>{if(e.dataset.ecAgeStacked==='1')return;const m=String(e.textContent||'').trim().match(/^(.+?)\s*[·•-]\s*(\d{1,3})\s*Jahre$/i);if(!m)return;e.textContent='';const n=document.createElement('span');n.className='ec-member-realname';n.textContent=m[1].trim();const a=document.createElement('small');a.className='ec-member-age';a.textContent=`(${m[2]} Jahre)`;e.append(n,a);e.dataset.ecAgeStacked='1';si(e,'display','flex');si(e,'flex-direction','column');si(e,'align-items','center');si(e,'gap','3px');si(e,'white-space','normal');si(a,'font-size','.72em');si(a,'font-weight','700');si(a,'line-height','1.1');si(a,'opacity','.92')})}function run(){paint('.member-card.member:not(.business),.member-card.ec-role-member:not(.business),.member-card:has(.ec-pro-member):not(.business)','member');paint('.member-card.business,.member-card.ec-role-business,.member-card:has(.ec-pro-business)','business');paint('.member-card.supporter,.member-card.ec-role-supporter,.member-card:has(.ec-pro-supporter)','supporter');paint('.member-card.admin,.member-card.head-admin,.member-card.ec-role-admin,.member-card.ec-role-head-admin,.member-card:has(.ec-pro-admin),.member-card:has(.ec-pro-head-admin)','admin');ages()}let scheduled=false;function schedule(){if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{scheduled=false;run()})}function start(){run();setTimeout(run,150);setTimeout(run,600);new MutationObserver(rs=>{if(rs.some(r=>r.addedNodes?.length))schedule()}).observe(document.body||document.documentElement,{subtree:true,childList:true})}document.readyState==='loading'?document.addEventListener('DOMContentLoaded',start,{once:true}):start();